api_examples:
// TypeScript example
const stream = client.events.stream({ resumeToken: token });
for await (const item of stream) {
  handle(item);
}
// resume via controller
await controller.resume(newToken);

// Go example
iter := client.EventsStream(ctx, opts)
for {
  it, err := iter.Next()
  if err == io.EOF { break }
  if err != nil { return err }
  process(it)
}
// resume
err := iter.Resume(token)
